/*
 * prog29_roman_numeral_parser.c
 *
 * Re‑implementation of the original obfuscated binary. The program
 * expects a single command‑line argument containing a Roman numeral.
 * It validates that the argument is a *canonical* Roman numeral (the one
 * produced by the greedy algorithm) and, if valid, prints its integer
 * value (0 … 3999).  Any error results in the single line "INVALID".
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 63          /* same limit used by the original binary */
#define MAX_ROMAN_VALUE 3999      /* historic upper bound for Roman numerals */

/* Symbol table – descending order, exactly the order used by the binary */
static const char * const SYMS[] = {
    "M",  "CM", "D",  "CD", "C",
    "XC", "L",  "XL", "X",  "IX",
    "V",  "IV", "I"
};

static const int VALUES[] = {
    1000, 900, 500, 400, 100,
     90,   50,  40,  10,   9,
      5,    4,   1
};

#define SYM_COUNT (sizeof(SYMS)/sizeof(SYMS[0]))

/* Convert a string to an upper‑case copy.
 * Returns 0 on success, -1 on failure (empty string, too long, or
 * characters outside the ASCII range that the original program could
 * upper‑case). */
static int make_upper(const char *src, char *dst, size_t dst_sz)
{
    size_t len = strlen(src);
    if (len == 0 || len >= dst_sz)   /* need space for terminating NUL */
        return -1;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = src[i];
        /* The original code only upper‑cased characters in the range
         * '`' (0x60) … '{' (0x7b). Anything else is left unchanged. */
        if (c >= '`' && c < '{')
            c -= 0x20;               /* turn lower‑case into upper‑case */
        dst[i] = (char)c;
    }
    dst[len] = '\0';
    return 0;
}

/* Greedy conversion of a *canonical* Roman numeral.
 * Returns the integer value on success, -1 on failure (non‑canonical,
 * illegal characters, overflow >3999). */
static int roman_to_int(const char *s)
{
    int total = 0;
    size_t pos = 0;
    size_t len = strlen(s);
    char rebuilt[256] = {0};   /* buffer for the canonical form */
    size_t rebuilt_len = 0;

    for (size_t sym = 0; sym < SYM_COUNT; ++sym) {
        const char *sym_str = SYMS[sym];
        size_t sym_len = strlen(sym_str);
        while (pos + sym_len <= len && strncmp(s + pos, sym_str, sym_len) == 0) {
            total += VALUES[sym];
            memcpy(rebuilt + rebuilt_len, sym_str, sym_len);
            rebuilt_len += sym_len;
            pos += sym_len;
        }
    }

    /* If we did not consume the whole input, it is not a canonical numeral */
    if (pos != len)
        return -1;

    /* Ensure the input matches the canonical representation produced by the
     * greedy algorithm (reject forms like "IIII" or "VX"). */
    if (strcmp(s, rebuilt) != 0)
        return -1;

    if (total > MAX_ROMAN_VALUE)
        return -1;

    return total;
}

int main(int argc, char *argv[])
{
    char upper[MAX_INPUT_LEN + 1];

    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (make_upper(argv[1], upper, sizeof(upper)) != 0) {
        puts("INVALID");
        return 0;
    }

    int value = roman_to_int(upper);
    if (value < 0) {
        puts("INVALID");
    } else {
        printf("%d\n", value);
    }
    return 0;
}
